IF OBJECT_ID(N'dbo.PatientResult',N'U') IS NULL BEGIN CREATE TABLE dbo.PatientResult(PatientResultId BIGINT IDENTITY(1,1) PRIMARY KEY,PatientResultUid UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID(),PatientUid UNIQUEIDENTIFIER NOT NULL,ResultType NVARCHAR(50) NOT NULL,ResultName NVARCHAR(200) NOT NULL,ResultDate DATETIME2(0) NOT NULL,ResultSummary NVARCHAR(MAX) NULL,ResultValue NVARCHAR(500) NULL,ResultUnit NVARCHAR(100) NULL,ReferenceRange NVARCHAR(200) NULL,ResultStatus NVARCHAR(50) NOT NULL DEFAULT N'New',ReviewedAt DATETIME2(0) NULL,ReviewedBy BIGINT NULL,ReviewNote NVARCHAR(1000) NULL,CreatedAt DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),CreatedBy BIGINT NULL,UpdatedAt DATETIME2(0) NULL,UpdatedBy BIGINT NULL,RowVersion ROWVERSION NOT NULL,CONSTRAINT UQ_PatientResult_Uid UNIQUE(PatientResultUid));CREATE INDEX IX_PatientResult_PatientUid_Status ON dbo.PatientResult(PatientUid,ResultStatus);CREATE INDEX IX_PatientResult_PatientUid_ResultDate ON dbo.PatientResult(PatientUid,ResultDate DESC);END;
GO
CREATE OR ALTER PROCEDURE dbo.PatientResult_GetByUid @PatientUid UNIQUEIDENTIFIER,@PatientResultUid UNIQUEIDENTIFIER AS BEGIN SET NOCOUNT ON;SELECT r.*,cu.DisplayName CreatedByDisplayName,uu.DisplayName UpdatedByDisplayName,ru.DisplayName ReviewedByDisplayName FROM dbo.PatientResult r LEFT JOIN dbo.ApplicationUser cu ON cu.UserId=r.CreatedBy LEFT JOIN dbo.ApplicationUser uu ON uu.UserId=r.UpdatedBy LEFT JOIN dbo.ApplicationUser ru ON ru.UserId=r.ReviewedBy WHERE r.PatientUid=@PatientUid AND r.PatientResultUid=@PatientResultUid;END;
GO
CREATE OR ALTER PROCEDURE dbo.PatientResult_GetByPatientUid @PatientUid UNIQUEIDENTIFIER,@StatusFilter NVARCHAR(50)=N'New' AS BEGIN SET NOCOUNT ON;IF @StatusFilter NOT IN(N'New',N'Reviewed',N'All')SET @StatusFilter=N'New';SELECT r.*,cu.DisplayName CreatedByDisplayName,uu.DisplayName UpdatedByDisplayName,ru.DisplayName ReviewedByDisplayName FROM dbo.PatientResult r LEFT JOIN dbo.ApplicationUser cu ON cu.UserId=r.CreatedBy LEFT JOIN dbo.ApplicationUser uu ON uu.UserId=r.UpdatedBy LEFT JOIN dbo.ApplicationUser ru ON ru.UserId=r.ReviewedBy WHERE r.PatientUid=@PatientUid AND(@StatusFilter=N'All' OR r.ResultStatus=@StatusFilter)ORDER BY r.ResultDate DESC,r.CreatedAt DESC;END;
GO
CREATE OR ALTER PROCEDURE dbo.PatientResult_Create @PatientUid UNIQUEIDENTIFIER,@ResultType NVARCHAR(50),@ResultName NVARCHAR(200),@ResultDate DATETIME2(0),@ResultSummary NVARCHAR(MAX)=NULL,@ResultValue NVARCHAR(500)=NULL,@ResultUnit NVARCHAR(100)=NULL,@ReferenceRange NVARCHAR(200)=NULL,@CreatedBy BIGINT=NULL AS BEGIN SET NOCOUNT ON;IF NOT EXISTS(SELECT 1 FROM dbo.Patient WHERE PatientUid=@PatientUid AND IsDeleted=0)THROW 51300,'Patient not found.',1;IF NULLIF(LTRIM(RTRIM(@ResultName)),N'') IS NULL THROW 51301,'Result name is required.',1;IF @ResultType NOT IN(N'Lab',N'Imaging',N'Diagnostic Test',N'Other')SET @ResultType=N'Other';DECLARE @Uid UNIQUEIDENTIFIER=NEWID();INSERT dbo.PatientResult(PatientResultUid,PatientUid,ResultType,ResultName,ResultDate,ResultSummary,ResultValue,ResultUnit,ReferenceRange,CreatedBy)VALUES(@Uid,@PatientUid,@ResultType,LTRIM(RTRIM(@ResultName)),@ResultDate,NULLIF(@ResultSummary,N''),NULLIF(@ResultValue,N''),NULLIF(@ResultUnit,N''),NULLIF(@ReferenceRange,N''),@CreatedBy);EXEC dbo.PatientResult_GetByUid @PatientUid,@Uid;END;
GO
CREATE OR ALTER PROCEDURE dbo.PatientResult_Update @PatientUid UNIQUEIDENTIFIER,@PatientResultUid UNIQUEIDENTIFIER,@ResultType NVARCHAR(50),@ResultName NVARCHAR(200),@ResultDate DATETIME2(0),@ResultSummary NVARCHAR(MAX)=NULL,@ResultValue NVARCHAR(500)=NULL,@ResultUnit NVARCHAR(100)=NULL,@ReferenceRange NVARCHAR(200)=NULL,@UpdatedBy BIGINT=NULL AS BEGIN SET NOCOUNT ON;IF EXISTS(SELECT 1 FROM dbo.PatientResult WHERE PatientUid=@PatientUid AND PatientResultUid=@PatientResultUid AND ResultStatus=N'Reviewed')THROW 51302,'Reviewed results cannot be edited.',1;IF NULLIF(LTRIM(RTRIM(@ResultName)),N'') IS NULL THROW 51301,'Result name is required.',1;IF @ResultType NOT IN(N'Lab',N'Imaging',N'Diagnostic Test',N'Other')SET @ResultType=N'Other';UPDATE dbo.PatientResult SET ResultType=@ResultType,ResultName=LTRIM(RTRIM(@ResultName)),ResultDate=@ResultDate,ResultSummary=NULLIF(@ResultSummary,N''),ResultValue=NULLIF(@ResultValue,N''),ResultUnit=NULLIF(@ResultUnit,N''),ReferenceRange=NULLIF(@ReferenceRange,N''),UpdatedAt=SYSUTCDATETIME(),UpdatedBy=@UpdatedBy WHERE PatientUid=@PatientUid AND PatientResultUid=@PatientResultUid;IF @@ROWCOUNT=0 RETURN;EXEC dbo.PatientResult_GetByUid @PatientUid,@PatientResultUid;END;
GO
CREATE OR ALTER PROCEDURE dbo.PatientResult_MarkReviewed @PatientUid UNIQUEIDENTIFIER,@PatientResultUid UNIQUEIDENTIFIER,@ReviewNote NVARCHAR(1000)=NULL,@ReviewedBy BIGINT=NULL AS BEGIN SET NOCOUNT ON;UPDATE dbo.PatientResult SET ResultStatus=N'Reviewed',ReviewedAt=COALESCE(ReviewedAt,SYSUTCDATETIME()),ReviewedBy=COALESCE(ReviewedBy,@ReviewedBy),ReviewNote=COALESCE(ReviewNote,NULLIF(@ReviewNote,N'')),UpdatedAt=SYSUTCDATETIME(),UpdatedBy=@ReviewedBy WHERE PatientUid=@PatientUid AND PatientResultUid=@PatientResultUid;IF @@ROWCOUNT=0 RETURN;EXEC dbo.PatientResult_GetByUid @PatientUid,@PatientResultUid;END;
GO
